'use strict';

// MODULES //

var fetchBounded = require( '@data-apis/http/fetch-bounded' );
var HarvesterError = require( '@data-apis/errors/harvester-error' );


// MAIN //

/**
* Fetches and parses a bounded JSON resource.
*
* @param {string|URL} url - source URL
* @param {Object} [options] - fetch options
* @returns {Promise<Object>} response metadata and parsed value
*/
async function fetchJson( url, options ) {
	var result;
	var value;

	options = options || {};
	result = await fetchBounded( url, Object.assign( {}, options, {
		'maxBytes': options.maxBytes || ( 5 * 1024 * 1024 )
	} ) );
	try {
		value = JSON.parse( new TextDecoder( 'utf-8', { 'fatal': true } ).decode( result.bytes ) );
	} catch ( error ) {
		throw new HarvesterError( 'Invalid JSON response from ' + new URL( url ).origin + ': ' + error.message, {
			'code': 'INVALID_API_JSON',
			'cause': error
		} );
	}
	return Object.assign( {}, result, {
		'value': value
	} );
}


// EXPORTS //

module.exports = fetchJson;
